   555  static inline bool consume_list(pni_consumer_t* consumer, pni_consumer_t *subconsumer, uint32_t *count) {
   556    *subconsumer = (pni_consumer_t){.output_start=consumer->output_start+consumer->position, .position=0, .size=0};
   557    *count = 0;
   558    uint8_t type;
   559    if (!pni_consumer_readf8(consumer, &type)) return false;
   560    switch (type) {
   561      case PNE_LIST32: {
   562        uint32_t s;
   563        if (!pni_consumer_readf32(consumer, &s)) return false;
   564        *subconsumer = (pni_consumer_t){.output_start=consumer->output_start+consumer->position, .position=0, .size=s};
   565        consumer->position += s;
   566        return pni_consumer_readf32(subconsumer, count);
   567      }
   568      case PNE_LIST8: {
   569        uint8_t s;
   570        if (!pni_consumer_readf8(consumer, &s)) return false;
   571        *subconsumer = (pni_consumer_t){.output_start=consumer->output_start+consumer->position, .position=0, .size=s};
   572        consumer->position += s;
   573        uint8_t c;
   574        if (!pni_consumer_readf8(subconsumer, &c)) return false;
   575        *count = c;
   576        return true;
   577      }
   578      case PNE_LIST0:
   579        return true;
   580      default:
   581        pni_consumer_skip_value(consumer, type);
   582        return false;
   583    }
   584  }
